// contrast — lib/storage/src/content_manager/collections_ops.rs:25-32 (used by GET/aliases, NOT by delete)
fn validate_collection_exists(&self, collection_name: &str) -> Result<(), StorageError> {
    if !self.collection_exists(collection_name) {
        return Err(StorageError::not_found(format!(
            "Collection `{collection_name}` doesn't exist!")));   // -> HTTP 404
    }
    Ok(())
}
